{
  "prose": [
    {
      "key": "headline",
      "text": "Trade {arm:f64}'s {cost.gap.f64.prod.per_1k|usd} savings per 1,000 replies for {contrast.f64.persona.delta|abs|pts} points lower persona consistency."
    },
    {
      "key": "lede",
      "text": "{arm:f64} cuts cost by {cost.gap.f64.prod.per_1k|usd} per 1,000 replies while maintaining both guardrails, but drops character consistency across deeper turns. An explicit threshold on acceptable persona loss determines whether to adopt it or stay on {arm:prod}."
    },
    {
      "key": "flag.title",
      "text": "No trade rule declared"
    },
    {
      "key": "flag.text",
      "text": "The campaign set no explicit exchange rate between reply cost and persona adherence; the product team must choose whether the monthly savings justify the drop."
    },
    {
      "key": "decision.the_trade",
      "text": "{arm:f64} saves {cost.gap.f64.prod.per_1k|usd} per 1,000 replies ({price.prod.f64.persona.monthly_cost_gap|usd_whole} per month) against a loss of {contrast.f64.persona.delta|abs|pts} points ({contrast.f64.persona.interval|pts}) on Stays in character."
    },
    {
      "key": "decision.where_it_flips",
      "text": "{arm:f64} wins if a point of character consistency is worth under {price.prod.f64.persona.per_point|usd} per 1,000 replies; above that price, keep {arm:prod}."
    },
    {
      "key": "decision.our_lean",
      "text": "Lean toward {arm:f64}: it clears both guardrails and preserves tone on early turns while delivering substantial cost and latency gains."
    },
    {
      "key": "decision.what_settles_it",
      "text": "Human evaluation on live long-context dialogs to confirm whether users notice the persona drift after five turns."
    },
    {
      "key": "summary.0.title",
      "text": "Reply cost across candidates"
    },
    {
      "key": "summary.1.title",
      "text": "Stays in character adherence"
    },
    {
      "key": "sections.contrasts.eyebrow",
      "text": "Candidate differences"
    },
    {
      "key": "sections.contrasts.headline",
      "text": "Challengers drop character adherence while meeting or breaching secondary criteria"
    },
    {
      "key": "sections.contrasts.takeaway",
      "text": "Points show paired differences against {arm:prod} with 95% uncorrected intervals; zero represents no difference."
    },
    {
      "key": "sections.contrasts.title",
      "text": ""
    },
    {
      "key": "sections.contrasts.caption",
      "text": "Differences are uncorrected across challengers."
    },
    {
      "key": "sections.depth.eyebrow",
      "text": "Turn depth breakdown"
    },
    {
      "key": "sections.depth.headline",
      "text": "Character drift accelerates as conversation length increases"
    },
    {
      "key": "sections.depth.takeaway",
      "text": "{arm:f64} remains near {arm:prod} during early turns but falls to {strata.depth:11+.f64.persona.mean|pct} beyond ten turns."
    },
    {
      "key": "sections.depth.title",
      "text": ""
    },
    {
      "key": "sections.depth.caption",
      "text": ""
    },
    {
      "key": "sections.scenarios.eyebrow",
      "text": "Scenario sensitivity"
    },
    {
      "key": "sections.scenarios.headline",
      "text": "Banter and user corrections drive the largest consistency drops"
    },
    {
      "key": "sections.scenarios.takeaway",
      "text": "Simpler intents like song intros show minimal drift across all evaluated models."
    },
    {
      "key": "sections.scenarios.title",
      "text": ""
    },
    {
      "key": "sections.scenarios.caption",
      "text": "Scenario figures are descriptive uncorrected sub-slices."
    },
    {
      "key": "durable_claims.0",
      "text": "{arm:f64} regresses Stays in character by {contrast.f64.persona.delta|abs|pts} points ({contrast.f64.persona.interval|pts}) while reducing cost by {cost.gap.f64.prod.per_1k|usd} per 1,000 replies."
    },
    {
      "key": "durable_claims.1",
      "text": "{arm:f64} drops from {strata.depth:1-2.f64.persona.mean|pct} in early turns to {strata.depth:11+.f64.persona.mean|pct} past ten turns on Stays in character."
    },
    {
      "key": "method.0.term",
      "text": "Sample size"
    },
    {
      "key": "method.0.text",
      "text": "{cases} cases evaluated with {scoreboard.prod.ran} trials per arm across synthetic persona dialogs."
    },
    {
      "key": "method.1.term",
      "text": "Primary judge"
    },
    {
      "key": "method.1.text",
      "text": "Evaluated by a {judged.persona.calibration} judge with agreement {judged.persona.agreement} across {judged.persona.calibration_ratings} calibration ratings."
    },
    {
      "key": "method.2.term",
      "text": "Guardrails"
    },
    {
      "key": "method.2.text",
      "text": "Music facts correct bounded at {criteria.facts.threshold|pct}; Declines to speculate bounded at {criteria.specul.threshold|pct}."
    },
    {
      "key": "method.3.term",
      "text": "Intervals"
    },
    {
      "key": "method.3.text",
      "text": "95% intervals based on paired differences against {arm:prod} without multi-test correction."
    },
    {
      "key": "method.4.term",
      "text": "Cost basis"
    },
    {
      "key": "method.4.text",
      "text": "Measured token usage multiplied by standard list prices per 1,000 replies."
    },
    {
      "key": "method.5.term",
      "text": "Volume projection"
    },
    {
      "key": "method.5.text",
      "text": "Monthly savings calculated on declared traffic volume of {meta.volume_per_month|int} replies."
    },
    {
      "key": "explore.title",
      "text": "Explore trade valuation"
    },
    {
      "key": "explore.recomputes",
      "text": "Adjusting the value per persona point recalculates net utility and flips the preference between {arm:prod} and {arm:f64} at {price.prod.f64.persona.per_point|usd}."
    },
    {
      "key": "explore.controls.price_per_point.title",
      "text": "Willingness to pay per consistency point ($/1k replies)"
    }
  ]
}

